entries[42986] = { ["name"] = "Die RG-GG", ["text"] = "Tausendwintersee\nEinzigartig (5)\nBenutzen: Feuert eine Hitzesuchrakete ab, die versucht, feindliche Panzer zu verfolgen.\nGranatwerfer für raketengetriebene Goblingranaten werden beim Tod fallen gelassen.\n\"Ausschließlich für Militärzwecke.\"" }
entries[42987] = { ["name"] = "Dunkelmond-Karte: Grandeur", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+90 Stärke\nBenötigt Stufe 80\nAnlegen: Ihr habt eine Chance, bei verursachter Heilung oder verursachtem Schaden den Effekt 'Grandeur' zu erhalten, der Eure Stärke, Beweglichkeit, Intelligenz oder Willenskraft 15 sec lang um 300 erhöht. Wirkt sich immer auf das höchste Attribut aus. (Procchance: 35%, 45s Abklingzeit)" }
entries[42988] = { ["name"] = "Dunkelmond-Karte: Illusion", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 80\nAnlegen: Erhöht die Zaubermacht um 100.\nBenutzen: Absorbiert 6 sec lang 1500 Schaden. Wenn der Schild auf irgendeine Art entfernt wird, gewinnt Ihr 1500 Mana zurück. (5 Min Abklingzeit)" }
entries[42989] = { ["name"] = "Dunkelmond-Karte: Berserker!", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 80\nAnlegen: Erhöht Eure Abhärtungswertung um 100.\nAnlegen: Ihr habt eine Chance, zum Berserker zu werden, wenn Ihr im Kampf Schaden verursacht oder erleidet. Erhöht 12 Sek. lang Eure kritische Trefferwertung um 35. Dieser Effekt ist bis zu 3-mal stapelbar. (Procchance: 50%)" }
entries[42990] = { ["name"] = "Dunkelmond-Karte: Tod", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 80\nAnlegen: Erhöht die kritische Trefferwertung um 85.\nAnlegen: Jedes Mal, wenn Ihr Schaden verursacht, besteht eine Chance, zusätzliche 1750 to 2250 Schattenschaden zu verursachen. (Procchance: 15%, 45s Abklingzeit)" }
