entries[43037] = { ["name"] = "Rezept: Fährtenlesersnacks", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (400)\nBenutzen: Lehrt Euch, wie man Fährtenlesersnacks zubereitet.\n\nFährtenlesersnacks\nBenötigt Stufe 70\nBenutzen: Stellt im Verlauf von 30 sec 22500 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und könnt 1 hour lang Wildtiere aufspüren.\nBenötigt Schaufelhauerflanke , Nordische Gewürze" }
entries[43038] = { ["name"] = "Die Nackte Bombe", ["text"] = "Benutzen: Verursacht 540 to 900 Feuerschaden und betäubt Ziele 3 sec lang in einem Radius von 3 Metern. Jeglicher Schaden wird den Effekt abbrechen. Unzuverlässig gegen Ziele über Stufe 90. (1 Min Abklingzeit)" }
entries[43039] = { ["name"] = "Schurkenkartenset", ["text"] = "Questgegenstand\nBenutzen: Kommuniziert mit der Geisterwelt, um eine Seance mit einem Wahrsager des Dunkelmondjahrmarkts zu erbitten. (5 Min Abklingzeit)" }
entries[43059] = { ["name"] = "Drakurus letzter Wunsch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 3 min\nBenutzen: Transportiert den Benutzer zu einer sicheren Entfernung von Voltarus.\n\"Irgendwo, bloß nicht hier...\"" }
