entries[43097] = { ["name"] = "Pelzbesatz - Angriffskraft", ["text"] = "Benutzen: Armschienen dauerhaft verzaubern, sodass sie die Angriffskraft um 130 erhöhen.\n\nEs können nur die Armschienen des Lederverarbeiters verzaubert werden und sie werden dadurch seelengebunden. Damit der Pelzbesatz wirkt, wird eine Lederverarbeitungsfertigkeit von mindestens 400 benötigt." }
entries[43098] = { ["name"] = "Ockerfarbene Pigmente", ["text"] = "\"Wird manchmal beim Mahlen von Wilddorn, Flitzdistel, Beulengras und Würgetang gewonnen.\"" }
