entries[43100] = { ["name"] = "Energieerfüllter Pilz", ["text"] = "Questgegenstand\n\"Mit diesem Pilz scheint irgendetwas nicht ganz zu stimmen.\"" }
entries[43101] = { ["name"] = "Bratenform", ["text"] = "Questgegenstand\nBenötigt Kochkunst (350)\nBenutzen: Kombiniert 4 energieerfüllte Pilze, 2 x kühles Fleisch und kocht das Ganze 2 Sek. lang über offenem Feuer. Voilà!" }
