entries[43317] = { ["name"] = "Vorlage: Ring der irdenen Macht", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelenschleifen (420)\nBenutzen: Lehrt Euch die Herstellung eines Rings der irdenen Macht.\n\nRing der irdenen Macht\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nFinger\n350 Rüstung\n+38 Stärke\n+34 Ausdauer\n\nBlauer Sockel\nSockelbonus: +4 Stärke\n\nBenötigt Stufe 78\nAnlegen: Erhöht Eure Ausweichwertung um 26.\nBenötigt Titanbarren (2), Äonenerde (2)" }
